{
  "name": "Feetech 智能舵机总线",
  "name_en": "Feetech Smart Servo Bus",
  "manufacturer": "Feetech",
  "description": "由 Feetech 总线型智能舵机及其串行通信链路组成的多电机控制系统，可连接多个机器人关节或夹爪执行器。它常用于机械臂、夹爪等实验室机器人平台，以读取位置等状态并下发目标位置等控制命令。",
  "description_en": "A multi-actuator control system built around Feetech bus-connected smart servos and their serial communication bus. It is commonly used in laboratory robotic platforms such as robot arms and grippers to read status such as position and send control commands such as target position.",
  "tag_hints": [
    "smart servo motors",
    "serial actuator bus",
    "robot joint control",
    "position feedback",
    "gripper actuation",
    "Feetech servos"
  ],
  "actions": [
    {
      "action_name": "auto-connect",
      "description": "连接到 Feetech 智能舵机总线以开始通信。",
      "description_en": "Connect to the Feetech smart servo bus to begin communication."
    },
    {
      "action_name": "auto-reconnect",
      "description": "重新连接到 Feetech 智能舵机总线。",
      "description_en": "Reconnect to the Feetech smart servo bus."
    },
    {
      "action_name": "auto-are_motors_configured",
      "description": "检查总线上的舵机是否已按预期的电机 ID 配置。",
      "description_en": "Check whether the servos on the bus are configured with the expected motor IDs."
    },
    {
      "action_name": "auto-find_motor_indices",
      "description": "扫描总线并查找已连接舵机的电机 ID。",
      "description_en": "Scan the bus and find the motor IDs of connected servos."
    },
    {
      "action_name": "auto-set_bus_baudrate",
      "description": "设置舵机总线的通信波特率。",
      "description_en": "Set the communication baud rate of the servo bus."
    },
    {
      "action_name": "auto-set_calibration",
      "description": "定义舵机位置与运动方向的校准参数。",
      "description_en": "Define calibration parameters for servo position and direction of motion."
    },
    {
      "action_name": "auto-apply_calibration_autocorrect",
      "description": "对舵机读数应用校准，并自动纠正超范围或整圈偏移问题。",
      "description_en": "Apply calibration to servo readings and automatically correct out-of-range or full-turn offset errors."
    },
    {
      "action_name": "auto-apply_calibration",
      "description": "对舵机位置读数应用校准转换。",
      "description_en": "Apply calibration conversion to servo position readings."
    },
    {
      "action_name": "auto-autocorrect_calibration",
      "description": "自动修正校准后出现的位置偏移或圈数错位问题。",
      "description_en": "Automatically correct position offsets or turn-count misalignment after calibration."
    },
    {
      "action_name": "auto-revert_calibration",
      "description": "将校准后的舵机位置值还原为原始电机单位。",
      "description_en": "Convert calibrated servo position values back to raw motor units."
    },
    {
      "action_name": "auto-avoid_rotation_reset",
      "description": "在舵机位置跨越编码器回绕点时补偿读数突变。",
      "description_en": "Compensate for position reading jumps when servo position crosses the encoder wrap point."
    },
    {
      "action_name": "auto-read_with_motor_ids",
      "description": "按指定电机 ID 从舵机读取指定寄存器数据。",
      "description_en": "Read a specified data register from servos by motor ID."
    },
    {
      "action_name": "auto-read",
      "description": "从一个或多个舵机读取指定数据项。",
      "description_en": "Read a specified data item from one or more servos."
    },
    {
      "action_name": "auto-write_with_motor_ids",
      "description": "按指定电机 ID 向舵机写入指定寄存器数据。",
      "description_en": "Write a specified data register to servos by motor ID."
    },
    {
      "action_name": "auto-write",
      "description": "向一个或多个舵机写入指定数据项。",
      "description_en": "Write a specified data item to one or more servos."
    },
    {
      "action_name": "auto-disconnect",
      "description": "断开与 Feetech 智能舵机总线的连接。",
      "description_en": "Disconnect from the Feetech smart servo bus."
    }
  ]
}

